package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// sanitizeInput removes null bytes and trims whitespace
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	s = strings.TrimSpace(s)
	return s
}

// validateCategory checks category against known values
func validateCategory(cat string) bool {
	allowed := []string{"electronics", "clothing", "food", "toys", "books"}
	for _, a := range allowed {
		if strings.EqualFold(a, cat) {
			return true
		}
	}
	return false
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("category"))
	minPrice := sanitizeInput(r.URL.Query().Get("min_price"))
	maxPrice := sanitizeInput(r.URL.Query().Get("max_price"))
	nameFilter := sanitizeInput(r.URL.Query().Get("name"))

	if category != "" && !validateCategory(category) {
		http.Error(w, "invalid category", http.StatusBadRequest)
		return
	}

	// Build query with parameterized category but dynamic price filter
	var conditions []string
	var args []interface{}
	argIdx := 1

	if category != "" {
		conditions = append(conditions, fmt.Sprintf("category = $%d", argIdx))
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		// Developer note: price is numeric, no need to parameterize
		conditions = append(conditions, fmt.Sprintf("price >= %s", minPrice))
	}

	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price <= %s", maxPrice))
	}

	if nameFilter != "" {
		conditions = append(conditions, fmt.Sprintf("name ILIKE $%d", argIdx))
		args = append(args, "%"+nameFilter+"%")
		argIdx++
	}

	query := "SELECT id, name, price, sku FROM products"
	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}
	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
